/* PLAN 061 1.4. aimFlow: samma settle-slinga som aimPin, men målscrollen
   räknas ur en FLOW-akts formel (p = (y + vh - top) / (höjd + vh)) i
   stället för pin-aktens. .process-chapter fick data-sc-act="flow" i
   B1 - en nästlad akt, samma motor. */
function aimFlow(el, p, extraDone){
  if (!el) return;
  var gen = ++aimPinGen, tries = 0;
  function settle(){
    if (gen !== aimPinGen) return;
    var rect = el.getBoundingClientRect();
    var top = rect.top + window.scrollY;
    var height = el.offsetHeight, vh = window.innerHeight;
    window.scrollTo(0, Math.round(top + p * (height + vh) - vh));
    dispatchEvent(new Event('resize'));
    var ps = parseFloat(getComputedStyle(el).getPropertyValue('--sc-ps'));
    tries++;
    if (tries < 10 && (isNaN(ps) || Math.abs(ps - p) > 0.002)){
      if (tries < 5) requestAnimationFrame(settle);
      else setTimeout(settle, 80);
    } else if (extraDone){ extraDone(); }
  }
  settle();
}
/* R24 FEL 4. Malpunkten raknas ur --tx-a/--tx-b, inte ur plan 061:s
   hardkodade .07 + .29*k/4. C3 bytte aktens fonster till utraknade tal
   (uppmatt 0,2258 / 0,1613) och planens 7.4 antog att malpunkterna
   foljde med automatiskt - de gor de inte: vid tes-till-ritning-3 lag
   arket 1329 px UNDER viewporten. Varje granskning som anvant
   forhandsvisningarna sedan R23 matte alltsa fel scrollage.
   tx = clamp(0,(sc_ps - txA)/txB, 1)  =>  sc_ps = txA + (k/4)*txB ger
   tx = k/4 exakt: -0 landar pa tx 0, -4 pa tx 1. */
if (mode && /^tes-till-ritning-[0-4]$/.test(mode)){
  var seamK = parseInt(mode.slice(-1), 10);
  var seamCh = document.querySelector('.process-chapter');
  var seamCs = seamCh ? getComputedStyle(seamCh) : null;
  var seamA = seamCs ? parseFloat(seamCs.getPropertyValue('--tx-a')) : NaN;
  var seamB = seamCs ? parseFloat(seamCs.getPropertyValue('--tx-b')) : NaN;
  if (isNaN(seamA)) seamA = .07;      /* oregistrerad/ej skriven an */
  if (isNaN(seamB)) seamB = .29;
  aimFlow(seamCh, seamA + (seamK / 4) * seamB);
}
/* curtain/chapter: ridån (§ ridån) är ren scroll - .process-chapter
   PLAN 057 2: stod tidigare i flödet utan egen akt; PLAN 061 B1 gav den
   data-sc-act="flow" (Blåkopian), men curtain/chapter siktar fortfarande
   geometriskt via ridaY - oförändrat i kod, som planen anger. Målet
   räknas geometriskt: tesens EGEN pinslut (dess sticky-spacers
   underkant) + en given höjd - se ridaY(100) nedan för hur talet räknas
   om i den nya (icke-överlappande) layouten. */
function ridaY(intoVh){
  var tesEl = document.getElementById('tes');
  if (!tesEl) return 0;
  var pinEnd = tesEl.getBoundingClientRect().top + window.scrollY + tesEl.offsetHeight - window.innerHeight;
  return pinEnd + intoVh * window.innerHeight / 100;

