content.content:
   window.innerWidth (clientWidth) med rullningslistens bredd - och
   translateX(-50%)-centrerad, så dess EGEN vänsterkant sitter vid
   -scrollbarWidth/2, inte 0. --pl-r/--pl-l räknade tidigare mot
   innerWidth/0, gav +5/-6px fel mot --x1/--x4 (uppmätt, contour2.json).
   Läser planets EGEN getBoundingClientRect() i stället - orört av
   067 (§ keep, C1). */
var planeElNow = process.querySelector('.tes-plane');
var planeBox = planeElNow ? planeElNow.getBoundingClientRect() : { left: 0, right: window.innerWidth };
chapterEl.style.setProperty('--pl-r', Math.max(0, planeBox.right - x4).toFixed(1) + 'px');
chapterEl.style.setProperty('--pl-l', Math.max(0, x1 - planeBox.left).toFixed(1) + 'px');
/* PLAN 067 C6/7.3. --sx1..--sx4: planets EGNA kanter/stationer (i
   planets egen bredd, inte arkets), i SAMMA chapter-relativa
   koordinater som --x1..--x4 - konturlinjerna interpolerar mellan
   dessa två uppsättningar på --tx (C6). Läst mot planeBox EGEN
   getBoundingClientRect(), aldrig window.innerWidth (plan 066
   fynd 2, samma disciplin som --pl-r/--pl-l ovan). */
var planeOffset = planeBox.left - C.left;
chapterEl.style.setProperty('--sx1', (0 - planeOffset).toFixed(1) + 'px');
chapterEl.style.setProperty('--sx2', (planeBox.width * 195.6 / 880 - planeOffset).toFixed(1) + 'px');
chapterEl.style.setProperty('--sx3', (planeBox.width * 469.3 / 880 - planeOffset).toFixed(1) + 'px');
chapterEl.style.setProperty('--sx4', (planeBox.width - 1 - planeOffset).toFixed(1) + 'px');
/* PLAN 067 C3/7.3. Klockan räknas, aldrig gissas (Target 7:15):
   draget (DRAW) halverat mot gårdagens hårdkodade 594/539px, och
   tx=1 nås när landningslinjen står på 0,86vh (tx-end-formeln). */
var chapterH = C.height;
var life = chapterH + vh;
var DRAW = window.innerWidth >= 768
  ? Math.min(300, Math.max(240, 0.30 * vh))
  : Math.min(260, Math.max(210, 0.28 * vh));
var txB = DRAW / life;
var txEnd = (dn + 0.14 * vh) / life;
var txA = txEnd - txB;
chapterEl.style.setProperty('--tx-a', txA.toFixed(4));
chapterEl.style.setProperty('--tx-b', txB.toFixed(4));
