"""Renderad bild av kapitelingangen (.cases-chapter) vid givna --cx-lagen.

fel 6:s kontroll: ingen mork/gra rektangel over papperet i nagot lage.
Bilden ar beviset, inte filen. wheel = riktig hjulscroll.
"""
import asyncio, sys, os
from playwright.async_api import async_playwright

URL = "http://localhost:3304/tests/alunix-r8/runs/V3d/index.html"
OUT = os.path.dirname(os.path.abspath(__file__))


async def scroll_until(pg, sel, target_cx, timeout=40):
    """Hjulscrolla till .cases-chapter sa att --cx narmar sig target_cx."""
    for _ in range(timeout):
        cx = await pg.evaluate(
            """(s) => { const e = document.querySelector(s);
                 if (!e) return null;
                 const v = parseFloat(getComputedStyle(e).getPropertyValue('--cx'));
                 return isNaN(v) ? null : v; }""", sel)
        if cx is None:
            return None
        if abs(cx - target_cx) <= 0.012:
            return cx
        # cx vaxer monotont med scrollY; stega i ratt riktning
        d = 40 if cx < target_cx else -40
        await pg.mouse.wheel(0, d)
        await pg.wait_for_timeout(12)
    return cx


async def main():
    w = int(sys.argv[1]); h = int(sys.argv[2])
    cxs = [float(x) for x in sys.argv[3].split(',')]
    tag = sys.argv[4]
    async with async_playwright() as p:
        b = await p.chromium.launch(ignore_default_args=['--hide-scrollbars'])
        pg = await b.new_page(viewport={'width': w, 'height': h})
        await pg.goto(URL)
        await pg.wait_for_timeout(2200)
        await pg.mouse.move(w // 2, h // 2)
        for target in cxs:
            got = await scroll_until(pg, '.cases-chapter', target)
            await pg.wait_for_timeout(420)
            got = await pg.evaluate(
                """() => { const e = document.querySelector('.cases-chapter');
                     const v = parseFloat(getComputedStyle(e).getPropertyValue('--cx'));
                     return {cx: isNaN(v) ? null : v, y: Math.round(window.scrollY),
                             plate: (() => { const q = document.querySelector('.chapter-plate');
                               const r = q.getBoundingClientRect();
                               return [Math.round(r.top), Math.round(r.bottom)]; })(),
                             chap: (() => { const r = document.querySelector('.cases-chapter').getBoundingClientRect();
                               return [Math.round(r.top), Math.round(r.bottom)]; })()}; }""")
            name = f"{tag}-{w}x{h}-cx{target:.2f}.png"
            await pg.screenshot(path=os.path.join(OUT, name))
            print(f"{name}  y={got['y']} cx={got['cx']}  plate={got['plate']} chapter={got['chap']}")
        await b.close()


asyncio.run(main())

