/* PLAN 067 5.3. Blåkopian baklänges: arket öppnar sig ut i
   .cases-chapter:s papper i stället för att krympa in i .tes-plane.
   Arkets VILANDE rektangel (sticky släppt) räknas analytiskt ur
   processTop/processH/stickens padding - measureAct skrollar aldrig
   sidan för att mäta ett läge, samma disciplin som --pl-* ovan.
   --cp-t/-r/-b/-l skrivs mot PLATTANS EGEN getBoundingClientRect(),
   aldrig window.innerWidth (plan 066 fynd 2). En gång per mätning. */
var caseEl = document.getElementById('case');
var plateEl = caseEl ? caseEl.querySelector('.chapter-plate') : null;
if (caseEl && plateEl && stick && chapterEl && sheetEl){
  var caseC = caseEl.getBoundingClientRect();
  var caseTopDoc = caseC.top + window.scrollY;
  var stickPadBottom = parseFloat(getComputedStyle(stick).paddingBottom) || 0;
  var arkBottomDoc = processTop + processH - stickPadBottom;
  var arkTopDoc = arkBottomDoc - pH;
  var cpUpIdeal = Math.max(0, caseTopDoc - arkTopDoc);
  var cpUp = Math.min(cpUpIdeal, fri);
  caseEl.style.setProperty('--cp-up', cpUp.toFixed(1) + 'px');
  var plateBox = plateEl.getBoundingClientRect();
  var plateTopDoc = caseTopDoc - cpUp;
  var plateBottomDoc = caseTopDoc + caseC.height;
  caseEl.style.setProperty('--cp-t', Math.max(0, arkTopDoc - plateTopDoc).toFixed(1) + 'px');
  caseEl.style.setProperty('--cp-b', Math.max(0, plateBottomDoc - arkBottomDoc).toFixed(1) + 'px');
  caseEl.style.setProperty('--cp-r', Math.max(0, plateBox.right - x4).toFixed(1) + 'px');
  caseEl.style.setProperty('--cp-l', Math.max(0, x1 - plateBox.left).toFixed(1) + 'px');
  /* 5.4: landningshårlinjens ankare, samma mönster som --dn ovan men
     mot casets EGEN rubrik (T2), i casets lokala koordinater. */
  var caseTitleEl = document.getElementById('case-title');
  if (caseTitleEl){
    var T2 = caseTitleEl.getBoundingClientRect();
    caseEl.style.setProperty('--cp-dn', Math.max(40, T2.top - caseC.top).toFixed(1) + 'px');
  }
}
var processRect2 = process.getBoundingClientRect();
processTop = processRect2.top + window.scrollY;

